        assert.equal(helpers.decideSmTriggerLabel({ jobParams: { customParams: {} } }), null);
        assert.equal(helpers.decideSmTriggerLabel({ jobParams: {} }), null);
        assert.equal(helpers.decideSmTriggerLabel({}), null);
    });

});

