+            if (gitResult.success && !gitResult.noNewCommit) {
+                partialPushed = true;
+                console.log('✅ Pushed partial work on branch', branchMissing);
+            }
+        }
+    } catch (e) {
+        console.warn('Could not push partial work:', e);
+    }
+    return partialPushed;
